const $=id=>document.getElementById(id);
const status=$('security-live-status'),receipt=$('security-live-receipt');
if(status&&receipt){
 const config=fetch('api-config.json').then(r=>r.json()).catch(()=>({baseUrl:''}));
 (async()=>{try{const {baseUrl=''}=await config,r=await fetch(baseUrl+'/api/health',{signal:AbortSignal.timeout(8000)}),data=await r.json();if(!r.ok)throw Error('Health check unavailable');const available=data.usage?Math.max(0,data.usage.limit-data.usage.used):'—';status.dataset.state='online';status.querySelector('span').textContent='LIVE AZURE RECEIPT';status.querySelector('strong').textContent='PROTECTED PATH ONLINE';status.querySelector('p').textContent=`Managed AI configured · persistent cache ${data.persistent_cache?'on':'off'} · ${available} requests available today`;receipt.textContent=JSON.stringify({checked_at:new Date().toISOString(),service:data.service,model:data.model,ai_configured:data.ai_configured,persistent_cache:data.persistent_cache,streaming:data.streaming,durable_checkpoints:data.durable_checkpoints,external_broadcast:data.external_broadcast,limits:data.usage},null,2);}catch(error){status.dataset.state='offline';status.querySelector('strong').textContent='CONTROL PLANE UNREACHABLE';status.querySelector('p').textContent='The public explanation remains available. Retry the live receipt after checking the Azure service.';receipt.textContent=JSON.stringify({checked_at:new Date().toISOString(),status:'unavailable',message:error.message},null,2);}})();
}
